\ifauthornotes
\newcommand{\editc}[3]{%
  \par\smallskip\noindent
  \begingroup
  \setlength{\fboxsep}{3pt}%
  \colorbox{#1!12}{%
    \parbox{\dimexpr\linewidth-2\fboxsep\relax}{%
