\def\ser@text#1{{\normalfont\ttfamily\expandafter\ser@split\detokenize{#1_}\@nil}}
\DeclareRobustCommand{\sername}[1]{\ifmmode\text{\ser@text{#1}}\else\ser@text{#1}\fi}
\makeatother
\newcommand{\ser}[2]{\ifrawseries\sername{#1}\else #2\fi}
